#!/usr/bin/env bash
set -euo pipefail
export AWS_PAGER=""

# Generated by RoleCraft — https://rolecraft.omhinge.cloud
# Creates a permissions policy and attaches it to an existing IAM group.

ROLE_NAME='analytics-reader'
PRINCIPAL_NAME='analytics-team'

# Permissions policy
cat > policy.json <<'ROLECRAFT_EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "S3ListReadList",
      "Effect": "Allow",
      "Action": "s3:ListBucket",
      "Resource": "arn:aws:s3:::data-lake",
      "Condition": {
        "StringLike": {
          "s3:prefix": [
            "reports/",
            "reports/*"
          ]
        }
      }
    },
    {
      "Sid": "S3ListReadObjects",
      "Effect": "Allow",
      "Action": [
        "s3:GetObject",
        "s3:GetObjectVersion"
      ],
      "Resource": "arn:aws:s3:::data-lake/reports/*"
    }
  ]
}
ROLECRAFT_EOF

POLICY_ARN=$(aws iam create-policy --policy-name="${ROLE_NAME}-policy" --policy-document file://policy.json --query Policy.Arn --output text)
aws iam attach-group-policy --group-name="$PRINCIPAL_NAME" --policy-arn="$POLICY_ARN"

echo "Attached the policy to group $PRINCIPAL_NAME."
